/* Effects from the supplied reference. Sounds are synthesized locally after touch only. */
(()=>{'use strict';
let effectsEnabled=false,ctx;
const status=document.getElementById('objectStatus');
const getAudio=()=>{const C=window.AudioContext||window.webkitAudioContext;if(!C){status.textContent='Som indisponível neste navegador. As imagens e explicações continuam acessíveis.';return null}ctx||=new C();ctx.resume();return ctx};
function tone(c,f,t,d,type='sine',gain=.07,end=f){const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(f,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),t+d);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(gain,t+.025);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+d+.02)}
function noise(c,t,d,cutoff){const b=c.createBuffer(1,Math.ceil(c.sampleRate*d),c.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=Math.random()*2-1;const s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=b;f.type='lowpass';f.frequency.value=cutoff;g.gain.setValueAtTime(.001,t);g.gain.linearRampToValueAtTime(.08,t+.03);g.gain.exponentialRampToValueAtTime(.001,t+d);s.connect(f);f.connect(g);g.connect(c.destination);s.start(t);s.stop(t+d)}
function play(kind){if(!effectsEnabled){status.textContent='Sons desligados. Ative o botão para ouvir os objetos.';return}if(window.speechSynthesis?.speaking){status.textContent='A explicação está tocando. Pare a voz para ouvir o objeto.';return}const c=getAudio();if(!c)return;const t=c.currentTime;const names={solar:'Conexão de ideias — efeito musical ilustrativo.',pages:'Páginas em investigação — efeito sonoro sintetizado.',grow:'Relação reconhecida — efeito musical ilustrativo.',success:'Conexão reconhecida!'};if(kind==='pages'){for(let i=0;i<3;i++)noise(c,t+i*.18,.15,1800+i*600)}else{const notes=kind==='grow'?[261.63,329.63,392,523.25]:kind==='success'?[523.25,659.25,783.99]:[659.25,987.77,1318.51];notes.forEach((f,i)=>tone(c,f,t+i*.12,.4,'sine',.055))}status.textContent=names[kind]||'Efeito sonoro solicitado.'}
document.querySelectorAll('.sound-object').forEach(b=>b.onclick=()=>{play(b.dataset.sound);if(typeof log==='function')log('som_objeto',b.dataset.sound)});
document.querySelectorAll('.read-object').forEach(b=>b.onclick=()=>speak(b.dataset.say));
document.getElementById('objectSound').onclick=e=>{effectsEnabled=!effectsEnabled;if(!effectsEnabled)ctx?.suspend();e.currentTarget.textContent=effectsEnabled?'🔊 Sons ao tocar: ligados':'🔇 Sons ao tocar: desligados';e.currentTarget.setAttribute('aria-pressed',String(!effectsEnabled));status.textContent=effectsEnabled?'Toque em um desenho para ouvir seu som.':'Sons dos objetos desligados.'};
document.getElementById('mute').addEventListener('click',()=>{effectsEnabled=false;ctx?.suspend();const b=document.getElementById('objectSound');b.textContent='🔇 Sons ao tocar: desligados';b.setAttribute('aria-pressed','true')});
document.getElementById('motion').onclick=e=>{const reduced=document.body.dataset.motion!=='reduce';document.body.dataset.motion=reduced?'reduce':'full';e.currentTarget.textContent=reduced?'Restaurar movimento':'Reduzir movimento';e.currentTarget.setAttribute('aria-pressed',String(reduced))};
const modal=document.getElementById('desafioModal'),feedback=document.getElementById('successMsg'),boss=document.getElementById('boss');
boss.onclick=()=>{feedback.hidden=true;modal.showModal();log('desafio_aberto')};document.getElementById('closeBoss').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});modal.addEventListener('close',()=>boss.focus());
modal.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const correct=b.dataset.answer==='1';feedback.dataset.correct=String(correct);feedback.hidden=false;feedback.replaceChildren();const h=document.createElement('h4');h.textContent=correct?'🎉 Você acertou!':'🔍 Vamos olhar outra vez';const p=document.createElement('p');p.textContent=correct?'Perspectiva e seleção precisam ser examinadas.':'Uma parte pode não representar o conjunto.';feedback.append(h,p);if(correct)play('success');log('desafio_revisao',b.dataset.answer)});
window.addEventListener('load',()=>{
 document.querySelectorAll('[data-scene]').forEach(b=>{if(window.ImageLearningScene){const art=b.querySelector('.picture-art');art.replaceChildren(window.ImageLearningScene(b.dataset.scene,b.getAttribute('aria-label').replace('Ouvir som de ','Ilustração: ')))}});
 const entry=document.getElementById('image-learning-open');if(entry)document.querySelector('.support-line').prepend(entry);
 const lab=document.getElementById('language-lab');if(lab)document.getElementById('workshopSlot').append(lab);
 const simple=document.querySelector('#intro button[aria-pressed=false]:not([id])');if(simple&&simple.textContent==='Leitura simples')document.querySelector('.support-line').append(simple);
 document.getElementById('language-lab')?.querySelector('figure')?.setAttribute('aria-label','Os elementos da frase selecionada');
});
window.addEventListener('pagehide',()=>ctx?.suspend());
})();
